const assert = require('assert');
const { capitalize, slugify } = require('../src/strings');

test('capitalize first letter', () => assert.strictEqual(capitalize('hello'), 'Hello'));
test('capitalize empty string', () => assert.strictEqual(capitalize(''), ''));

test('slugify lowercases and hyphenates', () => assert.strictEqual(slugify('Hello World'), 'hello-world'));
test('slugify collapses runs of symbols', () => assert.strictEqual(slugify('a  --  b!!c'), 'a-b-c'));
test('slugify trims leading and trailing hyphens', () => assert.strictEqual(slugify('  --Hi there!? '), 'hi-there'));
test('slugify strips Vietnamese diacritics', () => assert.strictEqual(slugify('Xin chào Việt Nam'), 'xin-chao-viet-nam'));
test('slugify maps đ/Đ to d', () => assert.strictEqual(slugify('Đường đi'), 'duong-di'));
test('slugify strips other Latin diacritics', () => assert.strictEqual(slugify('Crème Brûlée ñ'), 'creme-brulee-n'));
test('slugify keeps digits', () => assert.strictEqual(slugify('Top 10 of 2024'), 'top-10-of-2024'));
test('slugify empty and symbol-only input', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('!!! ???'), '');
});
test('slugify truncates to 50 characters', () => {
  assert.strictEqual(slugify('a'.repeat(80)), 'a'.repeat(50));
});
test('slugify truncated slug does not end with a hyphen', () => {
  const s = slugify('a'.repeat(49) + ' bbb');
  assert.strictEqual(s, 'a'.repeat(49));
  assert.ok(!s.endsWith('-'));
});
test('slugify slug of exactly 50 characters is kept', () => {
  assert.strictEqual(slugify('a'.repeat(25) + ' ' + 'b'.repeat(24)), 'a'.repeat(25) + '-' + 'b'.repeat(24));
});

